codes={r['code'].strip(): r for r in rows}
vd='"'$W/variants'"'
def norm(s): return re.sub(r'\\s+',' ',s).strip()
for f in sorted(glob.glob(vd+'/*.lean')):
    c=open(f).read().strip()
    r=codes.get(c)
    if r is None:
        # try normalized
        for k,v in codes.items():
            if norm(k)==norm(c): r=v; break
    if r:
        ev=r['evaluation']; off=ev['candidate']['length']
        print(os.path.basename(f), 'official', off, 'split', len(c.split()), 'nonspace', len(c.split()), 'chars', len(c))
    else:
        print(os.path.basename(f), 'NO MATCH', 'split', len(c.split()))
EOF"

